def level_from_xp(xp: int) -> int:
    level = 0
    while xp_for_level(level + 1) <= xp:
        level += 1
    return level

def xp_for_level(level: int) -> int:
    """Total XP to reach ``level``: 10 * (1^2 + 2^2 + ... + level^2)."""
    total = 0
    for i in range(1, level + 1):
        total += i * i * 10
    return total

